do $$declare s text;begin
select pg_get_functiondef('public.online_world_pre_latency(text,jsonb)'::regprocedure)into s;
if position('if m.x=49 and m.y=87'in s)=0 then raise exception 'Station boarding hook missing';end if;
s:=replace(s,'then 49 else 54 end;dy:=case when(v.rail_trip->>''reverse'')::boolean then 87 else 29 end;','then 51 else 50 end;dy:=case when(v.rail_trip->>''reverse'')::boolean then 101 else 39 end;');
s:=replace(s,'if action=''move''and (payload->>''y'')::int>=83 and(payload->>''y'')::int<=89 and(payload->>''x'')::int between 47 and 53','if action=''move''and (payload->>''y'')::int>=84 and(payload->>''y'')::int<=105 and(payload->>''x'')::int between 39 and 53');
s:=replace(s,'if m.x=49 and m.y=87','if m.x=51 and m.y=101');s:=replace(s,'if m.x=54 and m.y=29','if m.x=50 and m.y=39');
s:=replace(s,'then 49 else 54 end;sy:=case when board=''entry''then 88 else 28 end;','then 51 else 50 end;sy:=case when board=''entry''then 101 else 39 end;');execute s;
end$$;
-- Re-home only characters standing on a newly solid station object. Preserve rooms and inventory.
do $$declare m record;s jsonb;spot record;begin
for m in select a.* from online_adventure_members a where a.finished_at is null and a.floor=1 and a.rail_trip is null and ((a.x between 39 and 53 and a.y between 84 and 105)or(a.x between 48 and 62 and a.y between 27 and 42))loop
select snapshot into s from online_adventure_rooms where id=m.room_id;
if online_adventure_blocked(m.x,m.y,1,s)then select x,y into spot from generate_series(case when m.y>60 then 47 else 51 end,case when m.y>60 then 51 else 55 end)gx(x)cross join generate_series(case when m.y>60 then 79 else 23 end,case when m.y>60 then 82 else 25 end)gy(y)where not online_adventure_blocked(x,y,1,s)and not exists(select 1 from online_adventure_members o where o.room_id=m.room_id and o.floor=1 and o.finished_at is null and o.id<>m.id and o.x=gx.x and o.y=gy.y)order by abs(x-case when m.y>60 then 49 else 53 end)+abs(y-case when m.y>60 then 82 else 25 end)limit 1;if spot.x is not null then update online_adventure_members set x=spot.x,y=spot.y where id=m.id;end if;end if;
end loop;end$$;
do $$declare s text;begin select pg_get_functiondef('public.online_world(text,jsonb)'::regprocedure)into s;s:=replace(s,'py>=94','py>=108');execute s;end$$;
notify pgrst,'reload schema';
commit;
